package io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover;
import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import io.drozda.sandbox.mediator.ScenarioMediatorService;import io.drozda.sandbox.scenario.consumerfailureandpartitiontakeover.app.TakeoverScenarioStatus;import io.drozda.sandbox.visualization.ActiveScenarioRuntimeState;
@SpringBootTest(properties="spring.kafka.consumer.group-id=takeover-host-test-${random.uuid}")class ConsumerFailureScenarioTest {@Autowired ConsumerFailureEnvironment environment;@Autowired ScenarioMediatorService mediator;@Test void shouldGiveBothPartitionsAndQueuedRecordToSurvivor(){try{TakeoverScenarioStatus r=environment.observe("takeover-test");assertTrue(r.takenOver());assertEquals(2,r.initialOwners().values().stream().distinct().count());assertEquals(1,r.finalOwners().values().stream().distinct().count());assertTrue(r.finalOwners().values().stream().allMatch(r.survivor()::equals));assertTrue(r.observations().stream().anyMatch(v->"DURING FAILURE".equals(v.phase())&&v.consumer().equals(r.survivor())));ActiveScenarioRuntimeState runtime=mediator.execute("consumer-group-consumer-failure",ConsumerFailureScenarioStarter.OBSERVE_TAKEOVER,"visual-takeover-test");assertTrue(runtime.completed());assertEquals("READY",runtime.nodeStatuses().get("coordinator"));}finally{environment.stop();}}}
